blue='#165a9e'; red='#b23a35'
def chart(label):
 a=np.loadtxt(R/'results'/f'{label}_matlab.csv',delimiter=',',skiprows=1); a=a[a[:,0]<=30][::5]
 d=Drawing(250,255)
 for row,cols,limits,title in [(0,[1,3],(.65,1.35),'Speed / nominal speed'),(1,[2,4],(.4,.8),'Throttle opening fraction')]:
  x0,y0,w,h=35,145-row*120,205,80
  lo,hi=limits
  for yy in np.linspace(lo,hi,5):
   py=y0+(yy-lo)/(hi-lo)*h; d.add(Line(x0,py,x0+w,py,strokeColor='#dddddd',strokeWidth=.4));d.add(String(x0-4,py-2,f'{yy:.2f}',fontName='Body',fontSize=7,textAnchor='end'))
  for tt in [0,10,20,30]:
   xx=x0+w*tt/30; d.add(String(xx,y0-11,str(tt),fontName='Body',fontSize=7,textAnchor='middle'))
  d.add(Line(x0,y0,x0+w,y0,strokeWidth=.5));d.add(Line(x0,y0,x0,y0+h,strokeWidth=.5))
  for col,color in zip(cols,[blue,red]):
   points=[]
   for t,val in a[:,[0,col]]:points.extend([x0+w*t/30,y0+h*(val-lo)/(hi-lo)])
   d.add(PolyLine(points,strokeColor=color,strokeWidth=1.2,strokeDashArray=[4,2] if col in [3,4] else None))
  d.add(String(x0,y0+h+9,title,fontName='Bold',fontSize=8))
 d.add(String(137,5,'Time after load step (s)',fontName='Body',fontSize=8,textAnchor='middle'))
 d.add(String(35,244,'Closed loop (blue)   Open loop (red dashed)',fontName='Body',fontSize=8))
 renderPDF.drawToFile(d,str(R/'figures'/f'{label}.pdf'))
 return d

def schematic():
 d=Drawing(250,290)
 def box(x,y,w,h,text):
  d.add(Rect(x,y,w,h,fillColor='#f3f6f8',strokeColor='#333333',strokeWidth=.6))
  for j,line in enumerate(text.split('|')): d.add(String(x+w/2,y+h-11-j*10,line,fontName='Body',fontSize=8,textAnchor='middle'))
 def arrow(x,y,xx,yy):
  d.add(Line(x,y,xx,yy,strokeColor='#333333',strokeWidth=.7)); ang=math.atan2(yy-y,xx-x)
  for z in [-.4,.4]:d.add(Line(xx,yy,xx-5*math.cos(ang+z),yy-5*math.sin(ang+z),strokeWidth=.7))
