# Produce a complete IEEEtran source with identical prose and figures.
def tex_escape(s):
 s=html.unescape(s).replace('’', chr(39)).replace('“', chr(96)*2).replace('”', chr(39)*2)
 s=s.replace('%',r'\%').replace('&',r'\&').replace('_',r'\_')
 s=re.sub(r'<sub>(.*?)</sub>',lambda m:r'\ensuremath{_{\mathrm{'+m.group(1)+'}}}',s)
 s=re.sub(r'<[^>]+>','',s)
 replacements={'∂':r'\partial','π':r'\pi','Ω':r'\Omega','ω':r'\omega','τ':r'\tau','Δ':r'\Delta','ρ':r'\rho','ζ':r'\zeta','λ':r'\lambda','∞':r'\infty','∓':r'\mp','±':r'\pm','−':'-','×':r'\times','√':r'\surd','²':'{}^2','³':'{}^3','₀':'{}_0','ₚ':'{}_p','ᵢ':'{}_i','⁻¹¹':'{}^{-11}','⁻⁹':'{}^{-9}','⁻¹':'{}^{-1}','⁻⁴':'{}^{-4}','⁻⁵':'{}^{-5}','→':r'\to','↑':r'\uparrow','↓':r'\downarrow'}
 for ch,value in sorted(replacements.items(),key=lambda x:-len(x[0])):
  s=s.replace(ch,r'\ensuremath{'+value+'}')
 return s

latex_equations=iter(['q=Q\\Omega,\\quad A\\dot h=Q\\Omega-q_0', 'q_0=C_d a_0\\sqrt{2gH},\\quad \\Omega_0=q_0/Q', '\\Delta p=\\frac{\\rho}{2}\\left(\\frac{q}{C_r a_r}\\right)^2=\\Delta p_0w^2', '\\dot z=v,\\quad \\tau\\dot u+u=-k_p f(w)-k_i z', 'M\\dot v=-Dv+Ku-d', 'G_p(s)=\\frac{K}{Ms+D}', 'G_c(s)=\\frac{k_p+k_i/s}{\\tau s+1}', 'P(s)=\\tau Ms^3+(M+\\tau D)s^2', '{}+(D+Kk_p)s+Kk_i', '\\frac{V}{R}=\\frac{K(k_ps+k_i)}{P(s)}', '\\frac{V}{D_L}=\\frac{-s(\\tau s+1)}{P(s)}', '\\frac{U}{D_L}=\\frac{k_ps+k_i}{P(s)}', '\\tau M,\\quad M+\\tau D,', '\\frac{(M+\\tau D)(D+Kk_p)-\\tau MKk_i}{M+\\tau D},', 'Kk_i', '0<k_i<\\frac{(M+\\tau D)(D+Kk_p)}{\\tau MK}', 'P(s)=2.5s^3+5.5s^2+5s+1'])
tex=[r'\documentclass[conference]{IEEEtran}',r'\usepackage[T1]{fontenc}',r'\usepackage{amsmath,amssymb,graphicx,url}',r'\begin{document}',r'\title{A Water-Inventory Comparator for Steam-Engine Speed}',r'\author{\IEEEauthorblockN{vikas H R}\IEEEauthorblockA{Roll No. 23B2282\\ME319, IIT Bombay}}',r'\maketitle']
